    def partners(i,j):
        yield g[n-1-i][m-1-j]           # rot180
        yield g[i][m-1-j]               # mirror
        yield g[n-1-i][j]               # vertical flip
    changed=True
    while changed:
        changed=False
        for i in range(n):
            for j in range(m):
                if g[i][j]==3:
                    for v in partners(i,j):
                        if v!=3:
                            g[i][j]=v; changed=True; break
    return g
